class Node:
    __slots__ = ("key", "val", "prev", "next")

    def __init__(self, key=0, val=0):
        self.key = key
        self.val = val
        self.prev = None
        self.next = None


def lruCacheGets(capacity, ops):
    head, tail = Node(), Node()
    head.next = tail
    tail.prev = head
    table = {}

    def unlink(n):
        n.prev.next = n.next
        n.next.prev = n.prev

    def push_front(n):
        n.next = head.next
        n.prev = head
        head.next.prev = n
        head.next = n

    out = []
    for t, k, v in ops:
        n = table.get(k)
        if t == 0:
            if n is None:
                out.append(-1)
            else:
                unlink(n)
                push_front(n)
                out.append(n.val)
        elif n is not None:
            n.val = v
            unlink(n)
            push_front(n)
        else:
            if len(table) == capacity:
                lru = tail.prev
                unlink(lru)
                del table[lru.key]
            n = Node(k, v)
            table[k] = n
            push_front(n)
    return out
